head.script:
scwin.onpageload = function() {
console.log(WebSquare.util.isMobile());
console.log(WebSquare.util.isTouchDevice());
	autoComplete1.setValue("t2");

	var jsonData = [
    {"col1":"1","col2":"2","col3":"3"},
    {"col1":"11","col2":"12","col3":"13"}
    ];

    dataList2.setJSON(jsonData);

    var jsonData2 = [
    {"col1":"1","col2":"2","col3":"3"},
    {"col1":"11","col2":"12","col3":"13"}
    ];

    dataList2.setJSON(jsonData2);
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('autoComplete1_input').getAttribute('aria-activedescendant') === null;
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('autoComplete1_arrow').getAttribute('href') === null;
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('autoComplete1_itemTable').getAttribute('aria-expanded') === null;
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_div_arrow').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
